 15→/** Replace {{variable}} placeholders in a template string */
 16→function renderTemplate(template: string, variables: Record<string, string>): string {
 17→  return template.replace(/\{\{(\w+)\}\}/g, (_, key) => variables[key] ?? "");
 18→}
