 42→/** Send an email via Postmark API */
 43→async function sendViaPostmark(
 44→  apiToken: string,
 45→  from: { email: string; name: string },
 46→  to: string,
 47→  subject: string,
 48→  htmlContent: string
 49→): Promise<{ ok: boolean; status: number; body: string; errorCode?: number; errorMessage?: string }> {
 50→  const res = await fetch("https://api.postmarkapp.com/email", {
 51→    method: "POST",
 52→    headers: {
 53→      "Accept": "application/json",
 54→      "Content-Type": "application/json",
 55→      "X-Postmark-Server-Token": apiToken,
 56→    },
 57→    body: JSON.stringify({
 58→      From: `${from.name} <${from.email}>`,
 59→      To: to,
 60→      Subject: subject,
 61→      HtmlBody: htmlContent,
 62→      MessageStream: "outbound",
 63→    }),
 64→  });
 65→
 66→  const body = await res.text();
 67→  let errorCode: number | undefined;
 68→  let errorMessage: string | undefined;
 69→
 70→  if (!res.ok) {
 71→    try {
 72→      const parsed = JSON.parse(body);
 73→      errorCode = parsed.ErrorCode;
 74→      errorMessage = parsed.Message;
 75→    } catch { /* ignore */ }
 76→  }
 77→
 78→  return { ok: res.ok, status: res.status, body, errorCode, errorMessage };
 79→}
