 81→serve(async (req) => {
 82→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 83→
 84→  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 85→  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 86→  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 87→
 88→  try {
 89→    const { to, template_key, variables } = (await req.json()) as SendEmailRequest;
 90→
 91→    if (!to || !template_key) {
 92→      return new Response(JSON.stringify({ error: "Missing 'to' or 'template_key'" }), {
 93→        status: 400,
 94→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 95→      });
 96→    }
 97→
 98→    // Load platform config for Postmark credentials
 99→    const { data: config, error: configError } = await supabase
100→      .from("platform_config")
101→      .select("postmark_api_token, email_from_address, email_from_name, outbound_email_enabled, email_notify_ranking_complete, email_notify_resume_received")
102→      .limit(1)
103→      .single();
104→
105→    if (configError) throw new Error(`Config error: ${configError.message}`);
106→
107→    if (!config?.outbound_email_enabled) {
108→      return new Response(JSON.stringify({ error: "Outbound email is disabled", skipped: true }), {
109→        status: 200,
110→        headers: { ...corsHeaders, "Content-Type": "application/json" },
111→      });
112→    }
113→
114→    if (!config.postmark_api_token) {
115→      return new Response(JSON.stringify({ error: "Postmark API token not configured" }), {
116→        status: 400,
117→        headers: { ...corsHeaders, "Content-Type": "application/json" },
118→      });
119→    }
120→
121→    // Check per-template notification settings
122→    if (template_key === "ranking_complete" && !config.email_notify_ranking_complete) {
123→      return new Response(JSON.stringify({ skipped: true, reason: "Ranking complete notifications disabled" }), {
124→        status: 200,
125→        headers: { ...corsHeaders, "Content-Type": "application/json" },
126→      });
127→    }
128→    if (template_key === "resume_received" && !config.email_notify_resume_received) {
129→      return new Response(JSON.stringify({ skipped: true, reason: "Resume received notifications disabled" }), {
130→        status: 200,
131→        headers: { ...corsHeaders, "Content-Type": "application/json" },
132→      });
133→    }
134→
135→    // Load template
136→    const { data: template, error: tplError } = await supabase
137→      .from("email_templates")
138→      .select("subject, body_html")
139→      .eq("template_key", template_key)
140→      .single();
141→
142→    if (tplError || !template) {
143→      return new Response(JSON.stringify({ error: `Template '${template_key}' not found` }), {
144→        status: 404,
145→        headers: { ...corsHeaders, "Content-Type": "application/json" },
146→      });
147→    }
148→
149→    // Render template with variables
150→    const subject = renderTemplate(template.subject, variables);
151→    const htmlContent = renderTemplate(template.body_html, variables);
152→
153→    const fromEmail = config.email_from_address || "noreply@rankora.co";
154→    const fromName = config.email_from_name || "Rankora";
155→
156→    // Send via Postmark
157→    const result = await sendViaPostmark(
158→      config.postmark_api_token,
159→      { email: fromEmail, name: fromName },
160→      to,
161→      subject,
162→      htmlContent
163→    );
164→
165→    if (!result.ok) {
166→      const friendlyMessage = getPostmarkErrorMessage(
167→        result.errorCode || 0,
168→        result.errorMessage || "",
169→        fromEmail,
170→        to
171→      );
172→
173→      console.error("Postmark error:", result.status, result.body);
174→      return new Response(JSON.stringify({
175→        error: friendlyMessage,
176→        postmark_error_code: result.errorCode,
177→        postmark_raw: result.errorMessage,
178→      }), {
179→        status: 502,
180→        headers: { ...corsHeaders, "Content-Type": "application/json" },
181→      });
182→    }
183→
184→    return new Response(JSON.stringify({ success: true }), {
185→      status: 200,
186→      headers: { ...corsHeaders, "Content-Type": "application/json" },
187→    });
188→  } catch (err: unknown) {
189→    console.error("send-email error:", err);
190→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
191→      status: 500,
192→      headers: { ...corsHeaders, "Content-Type": "application/json" },
193→    });
194→  }
195→});
