import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

interface SendCandidateEmailRequest {
  resume_id: string;
  job_id: string;
  to_email: string;
  subject: string;
  body_html: string;
}

/** Send an email via Postmark API */
async function sendViaPostmark(
  apiToken: string,
  from: { email: string; name: string },
  to: string,
  subject: string,
  htmlContent: string
): Promise<{ ok: boolean; status: number; body: string; errorCode?: number; errorMessage?: string }> {
  const res = await fetch("https://api.postmarkapp.com/email", {
    method: "POST",
    headers: {
      "Accept": "application/json",
      "Content-Type": "application/json",
      "X-Postmark-Server-Token": apiToken,
    },
    body: JSON.stringify({
      From: `${from.name} <${from.email}>`,
      To: to,
      Subject: subject,
      HtmlBody: htmlContent,
      MessageStream: "outbound",
    }),
  });

  const body = await res.text();
  let errorCode: number | undefined;
  let errorMessage: string | undefined;

  if (!res.ok) {
    try {
      const parsed = JSON.parse(body);
      errorCode = parsed.ErrorCode;
      errorMessage = parsed.Message;
    } catch { /* ignore */ }
  }

  return { ok: res.ok, status: res.status, body, errorCode, errorMessage };
}

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

  // Verify JWT
  const authHeader = req.headers.get("Authorization");
  if (!authHeader) {
    return new Response(JSON.stringify({ error: "Missing authorization header" }), {
      status: 401,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  const token = authHeader.replace("Bearer ", "");
  const { data: { user }, error: authError } = await supabase.auth.getUser(token);
  if (authError || !user) {
    return new Response(JSON.stringify({ error: "Unauthorized" }), {
      status: 401,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  try {
    const { resume_id, job_id, to_email, subject, body_html } =
      (await req.json()) as SendCandidateEmailRequest;

    if (!resume_id || !job_id || !to_email || !subject || !body_html) {
      return new Response(
        JSON.stringify({ error: "Missing required fields: resume_id, job_id, to_email, subject, body_html" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Load platform config for Postmark credentials
    const { data: config, error: configError } = await supabase
      .from("platform_config")
      .select("postmark_api_token, email_from_address, email_from_name, outbound_email_enabled")
      .limit(1)
      .single();

    if (configError) throw new Error(`Config error: ${configError.message}`);

    if (!config?.outbound_email_enabled) {
      return new Response(JSON.stringify({ error: "Outbound email is disabled", skipped: true }), {
        status: 200,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    if (!config.postmark_api_token) {
      return new Response(JSON.stringify({ error: "Postmark API token not configured" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const fromEmail = config.email_from_address || "noreply@rankora.co";
    const fromName = config.email_from_name || "Rankora";

    // Send via Postmark
    const result = await sendViaPostmark(
      config.postmark_api_token,
      { email: fromEmail, name: fromName },
      to_email,
      subject,
      body_html
    );

    const logStatus = result.ok ? "sent" : "failed";

    // Log to outreach_log regardless of send result
    const { error: logError } = await supabase.from("outreach_log").insert({
      resume_id,
      job_id,
      type: "email",
      to_address: to_email,
      subject,
      status: logStatus,
      user_id: user.id,
    });

    if (logError) {
      console.error("Failed to log outreach:", logError.message);
    }

    if (!result.ok) {
      let errorMessage = result.errorMessage || `Postmark error (status ${result.status})`;
      if (result.errorCode === 412) {
        errorMessage = `Account pending approval — emails can only be sent to verified addresses while your Postmark account is being reviewed.`;
      } else if (result.errorCode === 406) {
        errorMessage = `Inactive recipient — ${to_email} has been marked as inactive due to previous bounces.`;
      } else if (result.errorCode === 300) {
        errorMessage = `Sender signature not found — ${fromEmail} is not verified in Postmark.`;
      } else if (result.errorCode === 401) {
        errorMessage = `Unauthorized — your Postmark API token is invalid or expired.`;
      }

      console.error("Postmark error:", result.status, result.body);
      return new Response(
        JSON.stringify({
          error: errorMessage,
          postmark_error_code: result.errorCode,
        }),
        { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    return new Response(JSON.stringify({ success: true }), {
      status: 200,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (err: unknown) {
    console.error("send-candidate-email error:", err);
    return new Response(
      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import { Mail, ExternalLink } from "lucide-react";

export interface EmailOutreachDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  candidateName: string;
  candidateEmail: string;
  jobTitle: string;
  matchScore: number;
  resumeId: string;
  jobId: string;
}

function buildDefaultTemplate(candidateName: string, jobTitle: string, matchScore: number): string {
  return `Hi ${candidateName},\n\nWe reviewed your application for the ${jobTitle} position and were impressed with your profile (${matchScore}% match).\n\nWe'd love to discuss this opportunity further. Would you be available for a brief call this week?\n\nBest regards`;
}

function buildDefaultSubject(jobTitle: string): string {
  return `Regarding Your Application – ${jobTitle}`;
}

const EmailOutreachDialog = ({
  open,
  onOpenChange,
  candidateName,
  candidateEmail,
  jobTitle,
  matchScore,
  resumeId,
  jobId,
}: EmailOutreachDialogProps) => {
  const [subject, setSubject] = useState(() => buildDefaultSubject(jobTitle));
  const [bodyText, setBodyText] = useState(() =>
    buildDefaultTemplate(candidateName, jobTitle, matchScore)
  );
  const [isSending, setIsSending] = useState(false);

  // Reset fields when the dialog opens with fresh values
  const handleOpenChange = (nextOpen: boolean) => {
    if (nextOpen) {
      setSubject(buildDefaultSubject(jobTitle));
      setBodyText(buildDefaultTemplate(candidateName, jobTitle, matchScore));
    }
    onOpenChange(nextOpen);
  };

  const bodyHtml = bodyText.replace(/\n/g, "<br>");

  const handleSend = async () => {
    if (!subject.trim()) {
      toast.error("Please enter a subject");
      return;
    }
    if (!bodyText.trim()) {
      toast.error("Please enter a message body");
      return;
    }

    setIsSending(true);
    try {
      const { data, error } = await supabase.functions.invoke("send-candidate-email", {
        body: {
          resume_id: resumeId,
          job_id: jobId,
          to_email: candidateEmail,
          subject: subject.trim(),
          body_html: bodyHtml,
        },
      });

      if (error) throw error;

      if (data?.skipped) {
        toast.warning("Outbound email is currently disabled. Enable it in Admin > Email Settings.");
        return;
      }

      if (data?.error) {
        throw new Error(data.error);
      }

      toast.success(`Email sent to ${candidateName}`);
      onOpenChange(false);
    } catch (err: any) {
      toast.error(err?.message || "Failed to send email");
    } finally {
      setIsSending(false);
    }
  };

  const mailtoHref = `mailto:${candidateEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(bodyText)}`;

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="sm:max-w-[540px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Mail className="h-4 w-4" />
            Email {candidateName}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* To — read-only */}
          <div className="space-y-1.5">
            <Label htmlFor="outreach-to">To</Label>
            <Input
              id="outreach-to"
              value={candidateEmail}
              readOnly
              className="bg-muted text-muted-foreground cursor-not-allowed"
            />
          </div>

          {/* Subject — editable */}
          <div className="space-y-1.5">
            <Label htmlFor="outreach-subject">Subject</Label>
            <Input
              id="outreach-subject"
              value={subject}
              onChange={(e) => setSubject(e.target.value)}
              placeholder="Email subject"
              disabled={isSending}
            />
          </div>

          {/* Body — editable */}
          <div className="space-y-1.5">
            <Label htmlFor="outreach-body">Message</Label>
            <Textarea
              id="outreach-body"
              value={bodyText}
              onChange={(e) => setBodyText(e.target.value)}
              rows={8}
              placeholder="Email body"
              disabled={isSending}
              className="resize-none"
            />
          </div>
        </div>

        <DialogFooter className="flex-col-reverse sm:flex-row gap-2">
          {/* Fallback: open in email client */}
          <Button
            variant="outline"
            size="sm"
            asChild
            className="gap-1.5"
          >
            <a href={mailtoHref} target="_blank" rel="noopener noreferrer">
              <ExternalLink className="h-3.5 w-3.5" />
              Open in Email Client
            </a>
          </Button>

          <Button onClick={handleSend} disabled={isSending} className="gap-1.5">
            <Mail className="h-3.5 w-3.5" />
            {isSending ? "Sending..." : "Send Email"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default EmailOutreachDialog;

